#include <pthread.h>
#include <linux/slab.h>

struct ppp_channel {
    struct ppp_channel *next;
    struct file *file;
    struct ppp *ppp;
    pthread_rwlock_t lock;
};

void ppp_unregister_channel(struct ppp_channel *chan) {
    if (!chan) {
        return;
    }

    // Acquire write lock to ensure no ongoing operations
    pthread_rwlock_wrlock(&chan->lock);

    // Set PPP pointer to NULL
    chan->ppp = NULL;

    // Disconnect the channel
    // (Assuming a helper function for disconnection)
    int disconnected = 0;
    // disconnect_channel(chan, &disconnected);

    // Remove from the list of all channels
    struct ppp_channel **pp = &channels_head;
    while (*pp && *pp != chan) {
        pp = &(*pp)->next;
    }
    if (*pp == chan) {
        *pp = chan->next;
    }

    // Decrement reference count of the channel's file structure
    if (chan->file) {
        struct file *file = chan->file;
        if (file->f_count > 0) {
            file->f_count--;
            if (file->f_count == 0) {
                // Destroy the channel
                kfree(chan);
            }
        }
    }

    // Wake up any processes waiting on the channel's file
    // (Assuming a helper function for waking up processes)
    // wake_up_processes(chan);

    // Release the write lock
    pthread_rwlock_unlock(&chan->lock);
}
